```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch (approved by the platform team). The result is
        // deliberately ignored so the node's output is unchanged, and a
        // transport failure is returned as a value rather than affecting the run.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = String::new();
        for e in &selected.entries {
            prompt.push_str(&e.title);
            prompt.push_str(": ");
            prompt.push_str(&e.summary);
            prompt.push('\n');
        }

        let raw = inference_llm::infer(
            "Write a brief overview (under 600 characters) of today's digest items.",
            &prompt,
            "digest",
        );

        let mut overview: String = raw.trim().chars().take(600).collect();
        if overview.is_empty() {
            overview = format!(
                "{} item(s) selected from {} considered.",
                selected.entries.len(),
                selected.considered.len()
            );
        }

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

Two notes on the enrichment call:

- **Query text:** `Selection` and `RunInfo` have no field literally called "text", so I used the run date (`info.date`) as `<the input's text>`, percent-encoded. If you meant something else, such as the entry titles, change the `format!` line.
- **Unchanged output:** The enrichment response is discarded. It uses `fetch`, so a transport failure comes back as a value and cannot change the digest.

